/**
 * The Returned Heir — structural test generated by compile:encounter (THR-1246).
 * Expected values are baked from the content package, so this file asserts the
 * encounter's actual shape rather than any template's.
 */

import { describe, expect, it } from 'vitest';
import { RETURNED_HEIR_TEMPLATE } from '../returned-heir';
import { expandSettings } from '../../settingClasses';
import { drawConsequenceHand, handAfterSwap } from '../../content-eval/consequenceDraw';

describe("The Returned Heir — template structure", () => {
  it('carries its identity', () => {
    expect(RETURNED_HEIR_TEMPLATE.id).toBe('encounter.town.returned_heir');
    expect(RETURNED_HEIR_TEMPLATE.reach).toBe('eye');
    expect(RETURNED_HEIR_TEMPLATE.rarityTier).toBe(2);
    expect(RETURNED_HEIR_TEMPLATE.steps).toHaveLength(2);
  });

  it('step 0 deals the authored hand', () => {
    const step = RETURNED_HEIR_TEMPLATE.steps[0];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['heir.show_the_scars', 'heir.deepen_his_sleep']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['darkness', 'force']);
  });

  it('step 1 deals the authored hand', () => {
    const step = RETURNED_HEIR_TEMPLATE.steps[1];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['heir.wake_a_conscience', 'heir.uncover_old_letters']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['light', 'spirit']);
  });
  it('derives its location subtypes from the declared envelope', () => {
    expect(RETURNED_HEIR_TEMPLATE.settings).toEqual(['urban', 'rural']);
    expect(RETURNED_HEIR_TEMPLATE.locationSubtypes).toEqual(expandSettings(['urban', 'rural']));
  });

  it('records exactly the hand its id draws (binding, THR-1145)', () => {
    expect(RETURNED_HEIR_TEMPLATE.consequenceDraw).toEqual(['relationship', 'movement']);
    expect(RETURNED_HEIR_TEMPLATE.consequenceDraw).toEqual(
      handAfterSwap(
        drawConsequenceHand({
          templateId: 'encounter.town.returned_heir',
          reach: 'eye',
          rarityTier: 2,
        }),
        RETURNED_HEIR_TEMPLATE.consequenceSwap,
      ),
    );
  });
});
